INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT132-S4-Q20$batch09$, 132, 4, 20, $batch09$Principle-Strengthen$batch09$, $batch09$Many workers who handled substance T in factories became seriously ill years later. We now know T caused at least some of their illnesses. Earlier ignorance of this connection does not absolve T's manufacturer of all responsibility. For had it investigated the safety of T before allowing workers to be exposed to it, many of their illnesses would have been prevented.$batch09$, $batch09$Which one of the following principles most helps to justify the conclusion above?$batch09$, $batch09$E$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=132 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT132-S4-Q20$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$Employees who are harmed by substances they handle on the job should be compensated for medical costs they incur as a result.$batch09$, $batch09$Wrong Conclusion$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT132-S4-Q20$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$Manufacturers should be held responsible only for the preventable consequences of their actions.$batch09$, $batch09$Wrong Direction$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT132-S4-Q20$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$Manufacturers have an obligation to inform workers of health risks of which they are aware.$batch09$, $batch09$Wrong Trigger$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT132-S4-Q20$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$Whether or not an action's consequences were preventable is irrelevant to whether a manufacturer should be held responsible for those consequences.$batch09$, $batch09$Opposite$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT132-S4-Q20$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$Manufacturers should be held responsible for the consequences of any of their actions that harm innocent people if those consequences were preventable.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT132-S4-Q20$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT132-S4-Q20$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$The manufacturer's earlier ignorance doesn't free it from all responsibility for the workers' illnesses.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$Substance T caused at least some of the illnesses. If the manufacturer had investigated T's safety before exposing workers, many of those illnesses would have been prevented.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The key evidence is that the harm was preventable. The conclusion is that the manufacturer bears some responsibility. So the rule needs "preventable" on the left and "responsible" on the right: if a manufacturer's action harms people and the harm was preventable, the manufacturer is responsible.$batch09$), (3, $batch09$Goal$batch09$, $batch09$Manufacturers are responsible for preventable harmful consequences of their actions.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT132-S4-Q20$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This says harmed employees should be compensated. It doesn't say who is responsible, so it doesn't reach the manufacturer.$batch09$), ($batch09$B$batch09$, $batch09$"Only" puts preventable on the right: responsible → preventable. That tells us when a manufacturer is not responsible, when the harm couldn't be prevented. It can't prove the manufacturer is responsible. Knowing the harm was preventable doesn't trigger anything.$batch09$), ($batch09$C$batch09$, $batch09$This covers risks the manufacturer was aware of. Here it was ignorant, so C never applies.$batch09$), ($batch09$D$batch09$, $batch09$If preventability is irrelevant, the argument's main evidence counts for nothing.$batch09$), ($batch09$E$batch09$, $batch09$The workers are innocent people harmed by T, and the evidence says the illnesses were preventable. Both conditions are met, so the manufacturer is held responsible. That's the conclusion.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT132-S4-Q20$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
